  1	/**
  2	 * Utility functions for resolving and injecting credentials into git remote URLs.
  3	 *
  4	 * Only HTTPS URLs are supported. SSH URLs (`git@...`) are left unchanged because
  5	 * SSH authentication is handled by the SSH agent or key — not by inline tokens.
  6	 */
  7	
  8	import type { GitCredentialEntry } from '../config/config.types.js';
  9	
 10	/**
 11	 * Extracts the hostname from an HTTPS git URL.
 12	 *
 13	 * @param url - The remote URL to inspect (e.g. "https://github.com/org/repo.git").
 14	 * @returns The hostname string (e.g. "github.com"), or `null` when the URL is
 15	 *   not a valid HTTPS URL (SSH, malformed, or empty).
 16	 */
 17	export function extractHost(url: string): string | null {
 18	    if (!url) return null;
 19	    try {
 20	        const parsed = new URL(url);
 21	        if (parsed.protocol !== 'https:') return null;
 22	        return parsed.hostname || null;
 23	    } catch {
 24	        return null;
 25	    }
 26	}
 27	
 28	/**
 29	 * Injects a token credential into an HTTPS URL as the userinfo component.
 30	 *
 31	 * If the credentials map contains an entry whose key matches the URL's hostname,
 32	 * the token is inserted as `https://<token>@<host>/...`. If no matching entry
 33	 * exists, or the URL is not HTTPS, the original URL is returned unchanged.
 34	 *
 35	 * The token is written as the username only (no password component) since
 36	 * Personal Access Tokens are typically passed in the username field.
 37	 *
 38	 * **Security note:** Token injection is performed via WHATWG URL object property
 39	 * assignment (`parsed.username = token`), NOT string concatenation. The URL
 40	 * serialiser automatically percent-encodes special characters in the token (e.g.
 41	 * `@`, `/`, `#`), preventing URL injection even with adversarially-crafted values.
 42	 *
 43	 * @param url         - The remote URL to modify.
 44	 * @param credentials - Map of hostname → token (e.g. `{ "github.com": "ghp_abc" }`).
 45	 * @returns The URL with credentials injected, or the original URL if no match.
 46	 */
 47	export function injectCredentials(url: string, credentials: Record<string, string>): string {
 48	    const host = extractHost(url);
 49	    if (host === null) return url;
 50	
 51	    const token = credentials[host];
 52	    if (!token) return url;
 53	
 54	    try {
 55	        const parsed = new URL(url);
 56	        parsed.username = token;
 57	        parsed.password = '';
 58	        return parsed.toString();
 59	    } catch {
 60	        return url;
 61	    }
 62	}
 63	
 64	/**
 65	 * Resolves the credential to use for a given repository URL.
 66	 *
 67	 * Resolution strategy:
 68	 *
 69	 * 1. **Explicit ID (`credentialId` provided):** Returns the entry whose `id`
 70	 *    matches `credentialId`, or `null` if no such entry exists (stale reference).
 71	 * 2. **Auto-selection (`credentialId` omitted):** Filters `credentials` by host
 72	 *    match against the URL's hostname.
 73	 *    - Exactly one match → returns that entry.
 74	 *    - Zero matches → returns `null` (no credentials configured for this host).
 75	 *    - Multiple matches → returns `null` (ambiguous; user must assign a
 76	 *      `CredentialId` to the repository explicitly).
 77	 *
 78	 * @param url          - The repository's remote URL.
 79	 * @param credentials  - The full array of configured credential entries.
 80	 * @param credentialId - Optional explicit credential ID to look up.
 81	 * @returns The matching `GitCredentialEntry`, or `null` when resolution fails.
 82	 */
 83	export function resolveCredential(
 84	    url: string,
 85	    credentials: GitCredentialEntry[],
 86	    credentialId?: string,
 87	): GitCredentialEntry | null {
 88	    if (credentialId !== undefined) {
 89	        return credentials.find((c) => c.id === credentialId) ?? null;
 90	    }
 91	
 92	    const host = extractHost(url);
 93	    if (host === null) return null;
 94	
 95	    const matches = credentials.filter((c) => c.host === host);
 96	    return matches.length === 1 ? matches[0] : null;
 97	}
 98	
 99	/**
100	 * Injects a single token into an HTTPS URL as the userinfo component.

100	 * Injects a single token into an HTTPS URL as the userinfo component.
101	 *
102	 * This is the simplified successor to `injectCredentials()`. It accepts a
103	 * pre-resolved token string directly (obtained from a {@link GitCredentialEntry}
104	 * via {@link resolveCredential}) instead of the full credentials map.
105	 *
106	 * The token is written as the WHATWG URL username only (no password component)
107	 * since Personal Access Tokens are typically passed in the username field.
108	 * Special characters in the token are automatically percent-encoded by the
109	 * URL serialiser — no string concatenation is used.
110	 *
111	 * @param url   - The remote URL to modify.
112	 * @param token - The credential token to inject.
113	 * @returns The URL with the token injected, or the original URL unchanged for
114	 *   non-HTTPS or malformed URLs.
115	 */
116	export function injectCredentialToken(url: string, token: string): string {
117	    const host = extractHost(url);
118	    if (host === null) return url;
119	
120	    try {
121	        const parsed = new URL(url);
122	        parsed.username = token;
123	        parsed.password = '';
124	        return parsed.toString();
125	    } catch {
126	        return url;
127	    }
128	}
129	
130	/**
131	 * Returns `true` when the URL contains an embedded username (and optional password)
132	 * in the userinfo section (e.g. `https://token@github.com/...`).
133	 *
134	 * Always returns `false` for non-HTTPS or malformed URLs.
135	 *
136	 * @param url - The URL to inspect.
137	 */
138	export function hasEmbeddedCredentials(url: string): boolean {
139	    if (!url) return false;
140	    try {
141	        const parsed = new URL(url);
142	        if (parsed.protocol !== 'https:') return false;
143	        return parsed.username !== '';
144	    } catch {
145	        return false;
146	    }
147	}
148	
149	/**
150	 * Redacts embedded HTTPS credentials from a URL or arbitrary string (e.g. a
151	 * git error message such as `"fatal: repository 'https://token@host/...' not found"`).
152	 *
153	 * Pure HTTPS URLs are sanitised via the WHATWG URL object (clean user/password
154	 * removal). All other inputs — non-HTTPS URLs, prose strings, and unparseable
155	 * values — fall through to a regex scrub that replaces any `https?://…@` pattern
156	 * with `https://***@`, preserving the host and path while redacting the token.
157	 *
158	 * @param input - The URL or string to sanitise.
159	 * @returns The sanitised string, or the original if no embedded credentials are
160	 *   found.
161	 */
162	export function stripEmbeddedCredentials(input: string): string {
163	    if (!input) return input;
164	    try {
165	        const parsed = new URL(input);
166	        if (parsed.protocol === 'https:') {
167	            parsed.username = '';
168	            parsed.password = '';
169	            return parsed.toString();
170	        }
171	        // Non-HTTPS valid URL (e.g. git:// or a prose string the WHATWG parser
172	        // accepted with a non-standard scheme like "fatal:") — fall through to
173	        // the regex scrub below to redact any embedded https credentials.
174	    } catch {
175	        // Not parseable as a URL — fall through to regex scrub.
176	    }
177	    // Scrub any embedded https credential patterns present in prose strings
178	    // (e.g. git error: "fatal: repository 'https://token@host/...' not found").
179	    return input.replace(/(https?:\/\/)[^@\s]*@/g, '$1***@');
180	}

