157	    }
158	}
159	
160	/**
161	 * Returns `true` when the URL contains an embedded username (and optional password)
162	 * in the userinfo section (e.g. `https://token@github.com/...`).
163	 *
164	 * Always returns `false` for non-HTTPS or malformed URLs.
165	 *
166	 * @param url - The URL to inspect.
167	 */
168	export function hasEmbeddedCredentials(url: string): boolean {
169	    if (!url) return false;
170	    try {
171	        const parsed = new URL(url);
172	        if (parsed.protocol !== 'https:') return false;
173	        return parsed.username !== '';
174	    } catch {
175	        return false;
176	    }
177	}
178	
179	/**
180	 * Redacts embedded HTTPS credentials from a URL or arbitrary string (e.g. a
181	 * git error message such as `"fatal: repository 'https://token@host/...' not found"`).
182	 *
183	 * Pure HTTPS URLs are sanitised via the WHATWG URL object (clean user/password
184	 * removal). All other inputs — non-HTTPS URLs, prose strings, and unparseable
185	 * values — fall through to a regex scrub that replaces any `https?://…@` pattern
186	 * with `https://***@`, preserving the host and path while redacting the token.
187	 *
188	 * @param input - The URL or string to sanitise.
189	 * @returns The sanitised string, or the original if no embedded credentials are
190	 *   found.
191	 */
192	export function stripEmbeddedCredentials(input: string): string {
193	    if (!input) return input;
194	    try {
195	        const parsed = new URL(input);
196	        if (parsed.protocol === 'https:') {
197	            parsed.username = '';
198	            parsed.password = '';
199	            return parsed.toString();
200	        }

